const $=id=>document.getElementById(id);
const routes=[['01','Bonfire'],['03','Yell Practice'],['04','Gig Em'],['05','Bush School']];
let page='menu',index=0,route=0,history=[],audio=false,lastWheel=0,wheelTotal=0;
let settings={rate:1,volume:.5,vibration:2,contrast:false,large:false};
try{settings={...settings,...JSON.parse(localStorage.getItem('transit-settings')||'{}')}}catch{}
const save=()=>{try{localStorage.setItem('transit-settings',JSON.stringify(settings))}catch{}};
const routeName=()=>`Route ${routes[route][0]} — ${routes[route][1]}`;
const item=(label,action,icon='')=>({label,action,icon});
function go(next){history.push({page,index});page=next;index=0;render(true)}
function back(){const old=history.pop();if(old){page=old.page;index=0;render(true)}else if(page!=='menu'){page='menu';index=0;render(true)}}
function home(){history=[];page='routes';index=0;render(true)}
function menu(){history=[];page='menu';index=0;render(true)}
function speak(text,force=false){$('transcript').textContent=text;$('live').textContent=audio?'':text;if((audio||force)&&'speechSynthesis'in window){speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.rate=settings.rate;utterance.volume=settings.volume;utterance.lang='en-US';speechSynthesis.speak(utterance)}}
function pulse(){if(navigator.vibrate)navigator.vibrate([20*settings.vibration,40,20])}
let view;
function getView(){switch(page){
case 'routes':return {title:'Bus routes',intro:'Bus routes. Scroll to explore, then press Enter or Left-click to select.',items:routes.map((r,i)=>item(`Route ${r[0]} — ${r[1]}`,()=>{route=i;go('route')},'bus'))};
case 'route':return {title:'My Transit',detail:`<span class="hero-icon"><img src="assets/bus.png" width="45" height="45" alt="" style="background:#770404;border-radius:12px;padding:5px"></span><strong>${routeName()}</strong><small>Sample arrival · 8 minutes</small>`,intro:`${routeName()}. Your demo bus arrives in eight minutes.`,items:[item('Navigate to stop',()=>go('leave'),'↗'),item('More options',()=>go('more'),'•••')]};
case 'more':return {title:'Route options',items:[item('Navigate to stop',()=>go('leave')),item('Next departures',()=>go('departures')),item('Customize',()=>go('customize')),item('Contact support',()=>go('support'))]};
case 'leave':return {title:'Time to leave',detail:`<span class="hero-icon">↗</span><strong>Navigation started</strong><span>Head to Ross &amp; Bizzell.</span><small>Practice route · Bus in 8 minutes</small>`,intro:`Demo navigation started. Head to Ross and Bizzell for ${routeName()}.`,items:[item('Continue',()=>go('directions')),item('Cancel navigation',menu)]};
case 'directions':return {title:'Directions',detail:'<span class="hero-icon">↱</span><strong>Turn right</strong>In 100 feet.<small>Practice directions</small>',intro:'Practice directions. In 100 feet, turn right.',items:[item('Continue demo',()=>go('reached')),item('Repeat instruction',()=>repeat()),item('Cancel navigation',menu)]};
case 'reached':return {title:'Stop reached',detail:`<span class="hero-icon">✓</span><strong>Ross &amp; Bizzell</strong>Wait here for Route ${routes[route][0]}.`,intro:`You have arrived at Ross and Bizzell in this demo. Wait here for Route ${routes[route][0]}.`,items:[item('Accessibility info',()=>go('access')),item('Simulate bus arrival',()=>go('arrival')),item('Repeat instruction',()=>repeat()),item('Cancel navigation',menu)]};
case 'arrival':return {title:'Bus arrived',detail:`<span class="hero-icon">▣</span><strong>Route ${routes[route][0]} arrived</strong>This is your demo bus.`,items:[item('Confirm & board',()=>go('boarded')),item('Cancel navigation',menu)]};
case 'boarded':return {title:'You’re on your way',detail:`<span class="hero-icon">✓</span><strong>Journey complete</strong>${routeName()}<small>Thanks for trying My Transit.</small>`,items:[item('Back to menu',menu)]};
case 'departures':return {title:'Next departures',detail:`<strong>${routeName()}</strong>Sample departures<br>8 min · 23 min · 38 min`,items:[item('Navigate to stop',()=>go('leave')),item('Back to route',back)]};
case 'access':return {title:'Accessibility info',detail:'<strong>Sample bus features</strong>Wheelchair access<br>Audio announcements<br>Kneeling bus<br>Ramp available<small>Verify with transit before travel.</small>',intro:'Sample accessibility information: wheelchair access, audio announcements, kneeling bus, and ramp. Verify with your transit service before travel.',items:[item('Repeat details',()=>repeat()),...(history.at(-1)?.page==='reached'?[item('Cancel navigation',menu)]:[])]};
case 'menu':return {title:'Main menu',items:[item('Access routes',()=>go('routes'),'bus'),item('Customize',()=>go('customize'),'⚙'),item('Contact support',()=>go('support'),'?')]};
case 'customize':return {title:'Customize',items:[item('Audio settings',()=>go('audioSettings')),item('Vibration strength',()=>go('vibration')),item('Extra contrast',()=>toggle('contrast')),item(settings.large?'Smaller text':'Larger text',()=>toggle('large'))]};
case 'audioSettings':return {title:'Audio settings',items:[item(audio?'Spoken guidance: on':'Spoken guidance: off',toggleAudio),item('Voice speed',()=>go('rate')),item('Volume level',()=>go('volume'))]};
case 'rate':case 'volume':case 'vibration':{const title={rate:'Voice speed',volume:'Volume level',vibration:'Vibration strength'}[page];const value=page==='rate'?settings.rate.toFixed(1)+'×':page==='volume'?Math.round(settings.volume*100)+'%':['Off','Light','Medium','Strong'][settings.vibration];return {title,detail:`<div class="setting-value">${value}</div><div class="setting-hint">Scroll to adjust. Click an action below to activate.</div>`,adjust:true,items:[item(page==='vibration'?'Test vibration':'Test sound',()=>{if(page==='vibration'){pulse();speak(navigator.vibrate?'Vibration test requested.':'Vibration is unavailable on this device.')}else speak('Your journey. One turn away. This is your audio test.',true)}),item('Save & go back',back)]}}
case 'support':return {title:'Contact support',detail:'<strong>Prototype support</strong>No transit service is connected.<small>For real assistance, use your transit provider’s official contact details.</small>',items:[item('Back to menu',menu),item('Back to routes',home)]};
default:return {title:'Bus routes',items:[]};}}
function render(announce=false){view=getView();$('title').textContent=view.title;const backButton=$('back');backButton.disabled=!history.length;const backSelected=history.length&&!view.adjust&&index===-1;backButton.classList.toggle('selected',backSelected);if(backSelected)backButton.setAttribute('aria-current','true');else backButton.removeAttribute('aria-current');const content=$('content');content.innerHTML=(view.detail?`<div class="detail">${view.detail}</div>`:'')+view.items.map((o,i)=>`<button tabindex="-1" class="option ${i===index?'selected':''}" aria-label="${o.label}" ${i===index?'aria-current="true"':''} data-option="${i}">${o.icon==='bus'?'<img src="assets/bus.png" width="28" height="28" alt="">':o.icon?`<span aria-hidden="true">${o.icon}</span>`:''}<span>${o.label}</span>${page==='routes'?'':'<span class="chevron" aria-hidden="true">›</span>'}</button>`).join('');content.querySelectorAll('.option').forEach((el,i)=>el.addEventListener('click',()=>{index=i;select()}));if(!announce&&!view.adjust){const el=content.querySelector('.selected');if(el)content.scrollTop=Math.max(0,el.offsetTop-content.offsetTop-45)}else content.scrollTop=0;if(announce)speak(`${view.intro||view.title+'.'} ${backSelected?'Back':view.items[index]?.label||view.title}.`);}
function adjustValue(delta){if(!view.adjust)return;const key=page;if(key==='rate')settings.rate=Math.round(Math.max(.5,Math.min(2,settings.rate+delta*.1))*10)/10;if(key==='volume')settings.volume=Math.round(Math.max(0,Math.min(1,settings.volume+delta*.1))*10)/10;if(key==='vibration')settings.vibration=Math.max(0,Math.min(3,settings.vibration+delta));save();render();speak(`${view.title}. ${$('content').querySelector('.setting-value').textContent}`)}
function move(delta){const count=view.items.length+(history.length?1:0);index=Math.max(history.length?-1:0,Math.min(view.items.length-1,index+delta));render();pulse();speak(`${history.length&&index===-1?'Back':view.items[index]?.label||view.title}. ${history.length?index+2:index+1} of ${count}.`)}
function select(){if(history.length&&!view.adjust&&index===-1){back();pulse();return}view.items[index]?.action();pulse()}
function repeat(){speak(`${view.intro||view.title+'.'} ${$('content').querySelector('.detail')?.textContent||''} ${view.items[index]?.label||''}.`,true)}
function toggleAudio(){audio=!audio;$('audio').textContent=audio?'Spoken guidance on':'Enable spoken guidance';$('audio').setAttribute('aria-pressed',String(audio));if(audio&&!('speechSynthesis'in window)){audio=false;$('audio').setAttribute('aria-pressed','false');$('audio').textContent='Speech unavailable';speak('Spoken guidance is unavailable in this browser. Written guidance and keyboard controls remain available.');return}if(audio)repeat();else if('speechSynthesis'in window)speechSynthesis.cancel();if(page==='audioSettings')render()}
function applyPreferences(){document.body.classList.toggle('high-contrast',settings.contrast);document.body.classList.toggle('large-text',settings.large);$('contrast').checked=settings.contrast;$('large').checked=settings.large;$('large-label').textContent=settings.large?'Smaller text':'Larger text'}
function toggle(key){settings[key]=!settings[key];save();applyPreferences();if(page==='customize')render();speak(`${key==='contrast'?'Extra contrast':(settings.large?'Larger text':'Smaller text')} ${settings[key]?'on':'off'}.`)}
$('watch').addEventListener('wheel',e=>{e.preventDefault();const now=Date.now();if(now-lastWheel<180)return;wheelTotal+=e.deltaY;if(Math.abs(wheelTotal)>=30){(view.adjust?adjustValue:move)(Math.sign(wheelTotal));wheelTotal=0;lastWheel=now}},{passive:false});$('watch').addEventListener('contextmenu',e=>{e.preventDefault();back()});
document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey)return;const nativeControl=e.target.closest('button,input,a');if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(view.adjust)adjustValue(e.key==='ArrowDown'?1:-1);else move(e.key==='ArrowDown'?1:-1)}else if(e.key==='Enter'&&!nativeControl){e.preventDefault();select()}else if(e.key==='Escape'||e.key==='Backspace'){e.preventDefault();back()}else if(e.target.tagName!=='INPUT'&&e.key.toLowerCase()==='r'){e.preventDefault();repeat()}});
$('previous').onclick=()=>view.adjust?adjustValue(-1):move(-1);$('next').onclick=()=>view.adjust?adjustValue(1):move(1);$('select').onclick=select;$('crown').onclick=select;$('side').onclick=menu;$('back').onclick=back;$('menu').onclick=menu;$('home').onclick=e=>{e.preventDefault();menu()};$('audio').onclick=toggleAudio;$('start').onclick=()=>{if(!audio)toggleAudio();$('watch').focus()};$('repeat').onclick=repeat;['contrast','large'].forEach(key=>$(key).onchange=()=>toggle(key));
function clock(){ $('time').textContent=new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}clock();setInterval(clock,30000);applyPreferences();render();
